#include <nettle/chacha-poly1305.h>
#include <nettle/chacha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 40000 * 1024;
    uint8_t *pt = malloc(n);
    uint8_t *ct = malloc(n);
    uint8_t key[32], nonce[12], aad[32], tag[16];
    memset(pt, 1, n);
    memset(key, 2, 32);
    memset(nonce, 3, 12);
    memset(aad, 4, 32);

    struct chacha_poly1305_ctx ctx;
    int reps = 5;
    double t0 = now();
    for (int i = 0; i < reps; i++) {
        chacha_poly1305_set_key(&ctx, key);
        chacha_poly1305_set_nonce(&ctx, nonce);
        chacha_poly1305_update(&ctx, 32, aad);
        chacha_poly1305_encrypt(&ctx, n, ct, pt);
        chacha_poly1305_digest(&ctx, tag);
    }
    double t1 = now();
    printf("nettle chacha-poly1305: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    struct chacha_ctx cctx;
    t0 = now();
    for (int i = 0; i < reps; i++) {
        chacha_set_key(&cctx, key);
        chacha_set_nonce96(&cctx, nonce);
        chacha_crypt(&cctx, n, ct, pt);
    }
    t1 = now();
    printf("nettle chacha20 raw: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    /* counter offset: encrypt second half only */
    size_t half = n/2;
    /* align to 64 */
    half = (half / 64) * 64;
    t0 = now();
    for (int i = 0; i < reps; i++) {
        chacha_set_key(&cctx, key);
        chacha_set_nonce96(&cctx, nonce);
        uint8_t counter[8] = {0};
        /* counter is little-endian block count. Start at block half/64 + 1 (since crypt starts at counter 1? )
           We'll just measure raw speed of a second-half crypt with counter set. */
        uint64_t blk = half / 64;
        counter[0] = blk & 0xff;
        counter[1] = (blk >> 8) & 0xff;
        counter[2] = (blk >> 16) & 0xff;
        counter[3] = (blk >> 24) & 0xff;
        chacha_set_counter(&cctx, counter);
        chacha_crypt(&cctx, n - half, ct + half, pt + half);
    }
    t1 = now();
    printf("nettle chacha20 second half: %.4f s  %.1f MB/s (of half)\n", (t1-t0)/reps, ((n-half)/1e6)/((t1-t0)/reps));
    return 0;
}
