}

int main() {
    size_t n = 40000UL * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    memset(pt, 1, n);
    unsigned int key[8];
    unsigned int counter[4];
    memset(key, 2, sizeof(key));
    memset(counter, 0, sizeof(counter));
    /* nonce in counter[1..3], block counter in counter[0] */
    counter[0] = 1;

    int reps = 5;
    double t0 = now();
    for (int i = 0; i < reps; i++) {
        counter[0] = 1;
        ChaCha20_ctr32(ct, pt, n, key, counter);
    }
    double t1 = now();
    printf("ChaCha20_ctr32: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

