    unsigned char evp_key[32], iv[16];
    memset(evp_key, 2, 32);
    memset(iv, 0, 16);
    iv[0] = 1; /* counter LE = 1 */
    unsigned char *out = malloc(n + 64);
    int outl = 0, total;
    reps = 5;
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, evp_key, iv);
        total = 0;
        EVP_EncryptUpdate(ctx, out, &outl, pt, (int)n);
        total = outl;
        EVP_EncryptFinal_ex(ctx, out + total, &outl);
    }
    t1 = now();
    printf("EVP_chacha20: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    /* EVP chacha20-poly1305 */
    unsigned char nonce[12];
    memset(nonce, 3, 12);
    unsigned char tag[16];
    unsigned char aad[32];
    memset(aad, 4, 32);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, evp_key, nonce);
