        EVP_EncryptUpdate(ctx, out, &outl, pt, (int)n);
        total = outl;
        EVP_EncryptFinal_ex(ctx, out + total, &outl);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("EVP_chacha20_poly1305: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    /* parallel ChaCha20_ctr32 with 4 threads via fork? do pthreads */
    return 0;
}
