#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/evp.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

#define MAX_THREADS 12
typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->counter);
    return NULL;
}

static void parallel_crypt(unsigned char *out, const unsigned char *in, size_t n,
                           const unsigned int key[8], unsigned int start_counter,
                           int nthreads) {
    if (nthreads < 1) nthreads = 1;
    /* split into 64-byte aligned chunks */
    size_t blocks = n / 64;
    size_t rem = n % 64;
    size_t blocks_per = blocks / nthreads;
    pthread_t th[MAX_THREADS];
    job_t jobs[MAX_THREADS];
    size_t off = 0;
    int launched = 0;
    for (int t = 0; t < nthreads; t++) {
        size_t nb = blocks_per;
        if (t == nthreads - 1) nb = blocks - blocks_per * (nthreads - 1);
        size_t len = nb * 64;
        if (t == nthreads - 1) len += rem;
        jobs[t].out = out + off;
        jobs[t].in = in + off;
        jobs[t].len = len;
        memcpy(jobs[t].key, key, 32);
        memcpy(jobs[t].counter, &start_counter, 4); /* wrong endianness, fix below */
        /* counter is 4 little-endian uint32 words: block counter, then nonce words */
        /* We pass full counter from caller via start_counter being block index.
           nonce words are in key? No. We'll set them outside. Use global nonce. */
        off += len;
    }
    /* redo properly below in main */
}

/* nonce words stored globally for simplicity */
static unsigned int g_nonce[3];

static void *worker2(void *arg) {
    job_t *j = arg;
    unsigned int counter[4];
    counter[0] = j->counter[0];
    counter[1] = g_nonce[0];
    counter[2] = g_nonce[1];
    counter[3] = g_nonce[2];
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, counter);
    return NULL;
}

static void run(int nthreads, size_t n, unsigned char *out, unsigned char *in, unsigned int key[8]) {
    size_t blocks = n / 64;
    size_t rem = n % 64;
    size_t blocks_per = blocks / nthreads;
    pthread_t th[MAX_THREADS];
    job_t jobs[MAX_THREADS];
    size_t off = 0;
    unsigned int blk = 1; /* ChaCha20-Poly1305 starts encryption at counter 1 */
    for (int t = 0; t < nthreads; t++) {
        size_t nb = (t == nthreads - 1) ? (blocks - blocks_per * (nthreads - 1)) : blocks_per;
        size_t len = nb * 64;
        if (t == nthreads - 1) len += rem;
        jobs[t].out = out + off;
        jobs[t].in = in + off;
        jobs[t].len = len;
        memcpy(jobs[t].key, key, 32);
        jobs[t].counter[0] = blk;
        off += nb * 64;
        blk += (unsigned int)nb;
    }
    for (int t = 0; t < nthreads; t++) pthread_create(&th[t], NULL, worker2, &jobs[t]);
    for (int t = 0; t < nthreads; t++) pthread_join(th[t], NULL);
}

int main() {
    size_t n = 40000UL * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    unsigned char *ct2 = malloc(n);
    memset(pt, 0x5a, n);
    unsigned int key[8];
    for (int i = 0; i < 8; i++) key[i] = 0x01020304u * (i+1);
    g_nonce[0] = 0x11111111;
    g_nonce[1] = 0x22222222;
    g_nonce[2] = 0x33333333;

    /* single thread reference */
    unsigned int counter[4] = {1, g_nonce[0], g_nonce[1], g_nonce[2]};
    ChaCha20_ctr32(ct, pt, n, key, counter);

    for (int nt = 1; nt <= 8; nt *= 2) {
        int reps = 5;
        double t0 = now();
        for (int i = 0; i < reps; i++) run(nt, n, ct2, pt, key);
        double t1 = now();
        int match = memcmp(ct, ct2, n) == 0;
        printf("threads=%d  %.4f s  %.1f MB/s  match=%d\n", nt, (t1-t0)/reps, (n/1e6)/((t1-t0)/reps), match);
    }
    /* also 6 and 3 and 12 */
    for (int nt = 3; nt <= 12; nt += 3) {
        int reps = 5;
        double t0 = now();
        for (int i = 0; i < reps; i++) run(nt, n, ct2, pt, key);
        double t1 = now();
        int match = memcmp(ct, ct2, n) == 0;
        printf("threads=%d  %.4f s  %.1f MB/s  match=%d\n", nt, (t1-t0)/reps, (n/1e6)/((t1-t0)/reps), match);
    }
    return 0;
}
EOF
