#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/evp.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
int Poly1305_Init(void *ctx, const unsigned char key[32]);
int Poly1305_Update(void *ctx, const void *inp, size_t len);
int Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

#define MAX_THREADS 8
static unsigned int g_nonce[3];

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned int key[8];
    unsigned int block;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    unsigned int counter[4];
    counter[0] = j->block;
    counter[1] = g_nonce[0];
    counter[2] = g_nonce[1];
    counter[3] = g_nonce[2];
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, counter);
    return NULL;
}

static void parallel_chacha(unsigned char *out, const unsigned char *in, size_t n,
                            const unsigned int key[8], int nthreads) {
    size_t blocks = n / 64;
    size_t rem = n % 64;
    size_t blocks_per = blocks / nthreads;
    pthread_t th[MAX_THREADS];
    job_t jobs[MAX_THREADS];
    size_t off = 0;
    unsigned int blk = 1;
    for (int t = 0; t < nthreads; t++) {
        size_t nb = (t == nthreads - 1) ? (blocks - blocks_per * (nthreads - 1)) : blocks_per;
        size_t len = nb * 64 + ((t == nthreads - 1) ? rem : 0);
        jobs[t].out = out + off;
        jobs[t].in = in + off;
        jobs[t].len = len;
        memcpy(jobs[t].key, key, 32);
        jobs[t].block = blk;
        off += nb * 64;
        blk += (unsigned int)nb;
        pthread_create(&th[t], NULL, worker, &jobs[t]);
    }
    for (int t = 0; t < nthreads; t++) pthread_join(th[t], NULL);
}

/* store le64 */
static void le64(unsigned char *p, uint64_t v) {
    for (int i = 0; i < 8; i++) p[i] = (unsigned char)(v >> (8*i));
}

static void poly_tag(unsigned char tag[16], const unsigned char poly_key[32],
                     const unsigned char *aad, size_t aad_len,
                     const unsigned char *ct, size_t ct_len, void *pctx) {
    Poly1305_Init(pctx, poly_key);
    if (aad_len) Poly1305_Update(pctx, aad, aad_len);
    size_t aad_pad = (16 - (aad_len & 15)) & 15;
    unsigned char zeros[16] = {0};
    if (aad_pad) Poly1305_Update(pctx, zeros, aad_pad);
    if (ct_len) Poly1305_Update(pctx, ct, ct_len);
    size_t ct_pad = (16 - (ct_len & 15)) & 15;
    if (ct_pad) Poly1305_Update(pctx, zeros, ct_pad);
    unsigned char lens[16];
    le64(lens, aad_len);
    le64(lens+8, ct_len);
    Poly1305_Update(pctx, lens, 16);
    Poly1305_Final(pctx, tag);
}

int main() {
    size_t n = 40000UL * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    memset(pt, 0x5a, n);
    unsigned int key[8];
    unsigned char keyb[32];
    for (int i = 0; i < 32; i++) keyb[i] = (unsigned char)(i * 7 + 3);
    memcpy(key, keyb, 32);
    unsigned char nonce[12];
    for (int i = 0; i < 12; i++) nonce[i] = (unsigned char)(i + 9);
    memcpy(g_nonce, nonce, 12);
    unsigned char aad[32];
    memset(aad, 0xab, 32);

    size_t psz = Poly1305_ctx_size();
    void *pctx = malloc(psz);
    printf("poly ctx size %zu\n", psz);

    unsigned char otk[64];
    unsigned int counter0[4] = {0, g_nonce[0], g_nonce[1], g_nonce[2]};
    unsigned char zeros64[64] = {0};

    int nthreads = 6;
    int reps = 5;
    unsigned char tag[16];
    double t0 = now();
    for (int i = 0; i < reps; i++) {
        ChaCha20_ctr32(otk, zeros64, 64, key, counter0);
        parallel_chacha(ct, pt, n, key, nthreads);
        poly_tag(tag, otk, aad, 32, ct, n, pctx);
    }
    double t1 = now();
    printf("full parallel nt=%d: %.4f s  %.1f MB/s\n", nthreads, (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    /* compare with EVP */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char *out = malloc(n + 64);
    unsigned char tag2[16];
    int outl = 0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, keyb, nonce);
    int dummy = 0;
    EVP_EncryptUpdate(ctx, NULL, &dummy, aad, 32);
    EVP_EncryptUpdate(ctx, out, &outl, pt, (int)n);
    int total = outl;
    EVP_EncryptFinal_ex(ctx, out + total, &outl);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag2);
    printf("ct match %d\n", memcmp(ct, out, n) == 0);
    printf("tag match %d\n", memcmp(tag, tag2, 16) == 0);
    if (memcmp(tag, tag2, 16) != 0) {
        printf("tag ours: ");
        for (int i = 0; i < 16; i++) printf("%02x", tag[i]);
        printf("\ntag evp : ");
        for (int i = 0; i < 16; i++) printf("%02x", tag2[i]);
        printf("\n");
    }

    /* poly only speed */
    t0 = now();
    for (int i = 0; i < reps; i++) poly_tag(tag, otk, aad, 32, ct, n, pctx);
    t1 = now();
    printf("poly1305 only: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    /* chacha only */
    t0 = now();
    for (int i = 0; i < reps; i++) parallel_chacha(ct, pt, n, key, nthreads);
    t1 = now();
    printf("chacha only nt=%d: %.4f s  %.1f MB/s\n", nthreads, (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));
    return 0;
}
