#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

/* streaming copy using non-temporal stores if possible */
#define NTHREADS 6
static size_t g_n;

typedef struct { unsigned char *dst, *src; size_t n; } job;

static void *copy_worker(void *arg) {
    job *j = arg;
    /* 32-byte chunks */
    size_t n = j->n;
    unsigned char *d = j->dst, *s = j->src;
    size_t i = 0;
    for (; i + 32 <= n; i += 32) {
        __asm__ volatile(
            "vmovdqu (%1), %%ymm0\n\t"
            "vmovntdq %%ymm0, (%0)\n\t"
            :
            : "r"(d+i), "r"(s+i)
            : "ymm0", "memory");
    }
    for (; i < n; i++) d[i] = s[i];
    _mm_sfence();
    return NULL;
}

#include <immintrin.h>

static void *read_worker(void *arg) {
    job *j = arg;
    volatile unsigned long long acc = 0;
    size_t n = j->n & ~31ULL;
    unsigned char *s = j->src;
    __m256i x = _mm256_setzero_si256();
    for (size_t i = 0; i < n; i += 32) {
        x = _mm256_xor_si256(x, _mm256_loadu_si256((const __m256i*)(s+i)));
    }
    unsigned long long b[4];
    _mm256_storeu_si256((__m256i*)b, x);
    acc = b[0]^b[1]^b[2]^b[3];
    /* prevent optimize */
    if (acc == 0xdead) j->dst[0] = 1;
    return NULL;
}

int main() {
    size_t n = 64UL << 20; /* 64 MB */
    unsigned char *src = aligned_alloc(64, n);
    unsigned char *dst = aligned_alloc(64, n);
    memset(src, 1, n);

    /* single thread copy */
    double t0 = now();
    int reps = 10;
