#include <time.h>
static inline uint64_t rdtsc() {
    unsigned int lo, hi;
    __asm__ volatile("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi << 32) | lo;
}
int main() {
    struct timespec ts;
    uint64_t c0 = rdtsc();
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double t0 = ts.tv_sec + ts.tv_nsec*1e-9;
    /* busy loop ~0.5s */
    volatile uint64_t x = 0;
    while (1) {
        x += 1;
        if ((x & 0xFFFFFF) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            double t = ts.tv_sec + ts.tv_nsec*1e-9;
            if (t - t0 > 0.3) break;
        }
    }
    uint64_t c1 = rdtsc();
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double t1 = ts.tv_sec + ts.tv_nsec*1e-9;
    printf("elapsed %.3f s  cycles %llu  freq %.2f GHz\n", t1-t0, (unsigned long long)(c1-c0), (c1-c0)/(t1-t0)/1e9);
    return 0;
}
