#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <immintrin.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct { unsigned char *dst, *src; size_t n; } job;

static void *nt_copy(void *arg) {
    job *j = arg;
    size_t n = j->n & ~63ULL;
    unsigned char *d = j->dst, *s = j->src;
    for (size_t i = 0; i < n; i += 64) {
        __m256i a = _mm256_loadu_si256((const __m256i*)(s+i));
        __m256i b = _mm256_loadu_si256((const __m256i*)(s+i+32));
        _mm256_stream_si256((__m256i*)(d+i), a);
        _mm256_stream_si256((__m256i*)(d+i+32), b);
    }
    _mm_sfence();
    return NULL;
}

static void *read_only(void *arg) {
    job *j = arg;
    size_t n = j->n & ~63ULL;
    unsigned char *s = j->src;
    __m256i x = _mm256_setzero_si256();
    for (size_t i = 0; i < n; i += 64) {
        x = _mm256_xor_si256(x, _mm256_loadu_si256((const __m256i*)(s+i)));
        x = _mm256_xor_si256(x, _mm256_loadu_si256((const __m256i*)(s+i+32)));
    }
    volatile unsigned long long sink = _mm256_extract_epi64(x, 0);
    (void)sink;
    return NULL;
}

static void *write_only(void *arg) {
    job *j = arg;
    size_t n = j->n & ~63ULL;
    unsigned char *d = j->dst;
    __m256i z = _mm256_set1_epi8(1);
    for (size_t i = 0; i < n; i += 64) {
        _mm256_stream_si256((__m256i*)(d+i), z);
        _mm256_stream_si256((__m256i*)(d+i+32), z);
    }
    _mm_sfence();
    return NULL;
}

static void run(const char *name, void *(*fn)(void*), int nt, size_t n, unsigned char *src, unsigned char *dst, int reps, int traffic_factor) {
    pthread_t th[16];
    job jobs[16];
    size_t chunk = n / nt;
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int t = 0; t < nt; t++) {
            jobs[t].src = src + t * chunk;
            jobs[t].dst = dst + t * chunk;
            jobs[t].n = (t == nt - 1) ? (n - t * chunk) : chunk;
            pthread_create(&th[t], NULL, fn, &jobs[t]);
        }
        for (int t = 0; t < nt; t++) pthread_join(th[t], NULL);
    }
    double t1 = now();
    double secs = (t1 - t0) / reps;
    printf("%-12s nt=%2d  %.4f s  payload %.1f GB/s  bus %.1f GB/s\n",
           name, nt, secs, (n/1e9)/secs, (traffic_factor * n / 1e9) / secs);
}

int main() {
    size_t n = 256UL << 20;
    unsigned char *src = aligned_alloc(64, n);
    unsigned char *dst = aligned_alloc(64, n);
    memset(src, 1, n);
    memset(dst, 2, n);
    int reps = 8;
    for (int nt = 1; nt <= 6; nt++) {
        run("copy", nt_copy, nt, n, src, dst, reps, 2);
    }
    for (int nt = 1; nt <= 6; nt++) {
        run("read", read_only, nt, n, src, dst, reps, 1);
    }
    for (int nt = 1; nt <= 6; nt++) {
        run("write", write_only, nt, n, src, dst, reps, 1);
    }
    /* 40MB like problem */
    size_t n2 = 40000UL * 1024;
    printf("--- 40MB ---\n");
    for (int nt = 1; nt <= 6; nt++) {
        run("copy40", nt_copy, nt, n2, src, dst, 30, 2);
    }
    return 0;
}
