#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/evp.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
int Poly1305_Init(void *ctx, const unsigned char key[32]);
int Poly1305_Update(void *ctx, const void *inp, size_t len);
int Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

#define NT 4

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned int key[8];
    unsigned int block;
    unsigned int nonce[3];
    pthread_mutex_t mu;
    pthread_cond_t cv_go, cv_done;
    int go, quit, done;
} worker_t;

static void *worker(void *arg) {
    worker_t *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (!w->go && !w->quit) pthread_cond_wait(&w->cv_go, &w->mu);
        if (w->quit) break;
        w->go = 0;
        pthread_mutex_unlock(&w->mu);
        unsigned int counter[4] = {w->block, w->nonce[0], w->nonce[1], w->nonce[2]};
        ChaCha20_ctr32(w->out, w->in, w->len, w->key, counter);
        pthread_mutex_lock(&w->mu);
        w->done = 1;
        pthread_cond_signal(&w->cv_done);
    }
    pthread_mutex_unlock(&w->mu);
    return NULL;
}

static void le64(unsigned char *p, uint64_t v) {
    for (int i = 0; i < 8; i++) p[i] = (unsigned char)(v >> (8*i));
}

int main() {
    size_t n = 40000UL * 1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 0x5a, n);
    memset(ct, 0, n);

    worker_t ws[NT];
    pthread_t th[NT];
    size_t blocks = n / 64;
    size_t rem = n % 64;
    size_t blocks_per = blocks / NT;
    size_t off = 0;
    unsigned int blk = 1;
    for (int t = 0; t < NT; t++) {
        size_t nb = (t == NT - 1) ? (blocks - blocks_per * (NT - 1)) : blocks_per;
        memset(&ws[t], 0, sizeof(ws[t]));
        pthread_mutex_init(&ws[t].mu, NULL);
        pthread_cond_init(&ws[t].cv_go, NULL);
        pthread_cond_init(&ws[t].cv_done, NULL);
        ws[t].out = ct + off;
        ws[t].in = pt + off;
        ws[t].len = nb * 64 + ((t == NT - 1) ? rem : 0);
        ws[t].block = blk;
        off += nb * 64;
        blk += (unsigned int)nb;
        pthread_create(&th[t], NULL, worker, &ws[t]);
    }

    unsigned int key[8];
    unsigned char keyb[32];
    for (int i = 0; i < 32; i++) keyb[i] = (unsigned char)(i * 7 + 3);
    memcpy(key, keyb, 32);
    unsigned char nonce[12];
    for (int i = 0; i < 12; i++) nonce[i] = (unsigned char)(i + 9);
    unsigned int nonce_w[3];
    memcpy(nonce_w, nonce, 12);
    unsigned char aad[32];
    memset(aad, 0xab, 32);

    size_t psz = Poly1305_ctx_size();
    void *pctx = malloc(psz);
    unsigned char otk[64];
    unsigned char zeros64[64] = {0};
    unsigned int counter0[4] = {0, nonce_w[0], nonce_w[1], nonce_w[2]};
    unsigned char tag[16];

    int reps = 20;
    /* warmup */
    for (int t = 0; t < NT; t++) {
        memcpy(ws[t].key, key, 32);
        memcpy(ws[t].nonce, nonce_w, 12);
        pthread_mutex_lock(&ws[t].mu);
        ws[t].done = 0;
        ws[t].go = 1;
        pthread_cond_signal(&ws[t].cv_go);
        pthread_mutex_unlock(&ws[t].mu);
    }
    for (int t = 0; t < NT; t++) {
        pthread_mutex_lock(&ws[t].mu);
        while (!ws[t].done) pthread_cond_wait(&ws[t].cv_done, &ws[t].mu);
        pthread_mutex_unlock(&ws[t].mu);
    }

    double t0 = now();
    for (int r = 0; r < reps; r++) {
        /* keystream for poly key */
        ChaCha20_ctr32(otk, zeros64, 64, key, counter0);
        for (int t = 0; t < NT; t++) {
            memcpy(ws[t].key, key, 32);
            memcpy(ws[t].nonce, nonce_w, 12);
            pthread_mutex_lock(&ws[t].mu);
            ws[t].done = 0;
            ws[t].go = 1;
            pthread_cond_signal(&ws[t].cv_go);
            pthread_mutex_unlock(&ws[t].mu);
        }
        for (int t = 0; t < NT; t++) {
            pthread_mutex_lock(&ws[t].mu);
            while (!ws[t].done) pthread_cond_wait(&ws[t].cv_done, &ws[t].mu);
            pthread_mutex_unlock(&ws[t].mu);
        }
        /* poly */
        Poly1305_Init(pctx, otk);
        Poly1305_Update(pctx, aad, 32);
        Poly1305_Update(pctx, ct, n);
        unsigned char lens[16];
        le64(lens, 32);
        le64(lens + 8, n);
        Poly1305_Update(pctx, lens, 16);
        Poly1305_Final(pctx, tag);
    }
    double secs = (now() - t0) / reps;
    printf("pool nt=%d full: %.5f s  %.1f MB/s\n", NT, secs, (n/1e6)/secs);

    /* verify vs EVP */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char *out = malloc(n + 32);
    unsigned char tag2[16];
    int outl = 0, dummy = 0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, keyb, nonce);
    EVP_EncryptUpdate(ctx, NULL, &dummy, aad, 32);
    EVP_EncryptUpdate(ctx, out, &outl, pt, (int)n);
    int total = outl;
    EVP_EncryptFinal_ex(ctx, out + total, &outl);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag2);
    printf("match ct %d tag %d\n", memcmp(ct, out, n)==0, memcmp(tag, tag2, 16)==0);

    /* chacha only with pool */
    t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int t = 0; t < NT; t++) {
            pthread_mutex_lock(&ws[t].mu);
            ws[t].done = 0;
            ws[t].go = 1;
            pthread_cond_signal(&ws[t].cv_go);
            pthread_mutex_unlock(&ws[t].mu);
        }
        for (int t = 0; t < NT; t++) {
            pthread_mutex_lock(&ws[t].mu);
            while (!ws[t].done) pthread_cond_wait(&ws[t].cv_done, &ws[t].mu);
            pthread_mutex_unlock(&ws[t].mu);
        }
    }
    secs = (now() - t0) / reps;
    printf("pool chacha only: %.5f s  %.1f MB/s\n", secs, (n/1e6)/secs);

    /* poly only */
    t0 = now();
    for (int r = 0; r < reps; r++) {
        Poly1305_Init(pctx, otk);
        Poly1305_Update(pctx, aad, 32);
        Poly1305_Update(pctx, ct, n);
        unsigned char lens[16];
        le64(lens, 32);
        le64(lens + 8, n);
        Poly1305_Update(pctx, lens, 16);
        Poly1305_Final(pctx, tag);
    }
    secs = (now() - t0) / reps;
    printf("poly only: %.5f s  %.1f MB/s\n", secs, (n/1e6)/secs);
    return 0;
}
