{"command":"cat > floor_ext.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <string.h>
#include <stdint.h>

static PyObject *make_result(PyObject *ct) {
    PyObject *tag = PyBytes_FromStringAndSize("0123456789abcdef", 16);
    if (!tag) { Py_DECREF(ct); return NULL; }
    PyObject *res = PyDict_New();
    if (!res) { Py_DECREF(ct); Py_DECREF(tag); return NULL; }
    PyDict_SetItemString(res, "ciphertext", ct);
    PyDict_SetItemString(res, "tag", tag);
    Py_DECREF(ct);
    Py_DECREF(tag);
    return res;
}

/* Allocate output and memcpy plaintext into it. Absolute floor for producing a bytes result. */
static PyObject *copy_plain(PyObject *self, PyObject *args) {
    PyObject *problem;
    if (!PyArg_ParseTuple(args, "O", &problem)) return NULL;
    PyObject *pt = PyDict_GetItemString(problem, "plaintext");
    if (!pt || !PyBytes_Check(pt)) { PyErr_SetString(PyExc_TypeError, "pt"); return NULL; }
    Py_ssize_t n = PyBytes_GET_SIZE(pt);
    PyObject *ct = PyBytes_FromStringAndSize(NULL, n);
    if (!ct) return NULL;
    memcpy(PyBytes_AS_STRING(ct), PyBytes_AS_STRING(pt), (size_t)n);
    PyBytes_AS_STRING(ct)[0] ^= 1;
    return make_result(ct);
}

/* Write-only: allocate and fill with a constant. Lower bound on producing any 40MB bytes. */
static PyObject *write_only(PyObject *self, PyObject *args) {
    PyObject *problem;
    if (!PyArg_ParseTuple(args, "O", &problem)) return NULL;
    PyObject *pt = PyDict_GetItemString(problem, "plaintext");
    Py_ssize_t n = PyBytes_GET_SIZE(pt);
    PyObject *ct = PyBytes_FromStringAndSize(NULL, n);
    if (!ct) return NULL;
    memset(PyBytes_AS_STRING(ct), 0xA5, (size_t)n);
    return make_result(ct);
}

/* Reuse a single preallocated buffer: still must copy out to a new bytes to return. */
static char *g_buf = NULL;
static Py_ssize_t g_n = 0;

static PyObject *reuse_then_copy(PyObject *self, PyObject *args) {
    PyObject *problem;
    if (!PyArg_ParseTuple(args, "O", &problem)) return NULL;
    PyObject *pt = PyDict_GetItemString(problem, "plaintext");
    Py_ssize_t n = PyBytes_GET_SIZE(pt);
    if (g_n != n) {
        free(g_buf);
        g_buf = malloc((size_t)n);
        g_n = n;
    }
    memcpy(g_buf, PyBytes_AS_STRING(pt), (size_t)n);
    PyObject *ct = PyBytes_FromStringAndSize(g_buf, n);
    if (!ct) return NULL;
    return make_result(ct);
}

static PyMethodDef methods[] = {
    {"copy_plain", copy_plain, METH_VARARGS, ""},
    {"write_only", write_only, METH_VARARGS, ""},
    {"reuse_then_copy", reuse_then_copy, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef mod = {PyModuleDef_HEAD_INIT, "floor_ext", NULL, -1, methods};
PyMODINIT_FUNC PyInit_floor_ext(void) { return PyModule_Create(&mod); }
